// dynssz-certify emits Lean 4 certificates for SSZ types.
//
// For every requested Go type it builds the same go/types descriptor that
// dynssz-gen's code generation consumes, translates it into a codec
// expression over the verified combinator library (formal/lean/SszCert), and
// emits per-type canonicity and roundtrip theorem instances. Type-checking
// the generated file with `lake build` machine-checks those theorems for the
// concrete type layout the generator saw.
package main

import (
	"flag"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"log"
	"os"
	"sort"
	"strconv"
	"strings"

	"github.com/pk910/dynamic-ssz/codegen"
	"github.com/pk910/dynamic-ssz/ssztypes"
	"golang.org/x/tools/go/packages"
)

func main() {
	var (
		packagePath = flag.String("package", ".", "Go package to load")
		typeNames   = flag.String("types", "", "comma-separated type names to certify")
		outputFile  = flag.String("output", "Certified.lean", "output Lean file")
		verbose     = flag.Bool("v", false, "verbose output")
	)
	flag.Parse()

	if *typeNames == "" {
		log.Fatal("-types is required")
	}

	names := strings.Split(*typeNames, ",")
	for i := range names {
		names[i] = strings.TrimSpace(names[i])
	}

	if err := run(*packagePath, names, *outputFile, *verbose); err != nil {
		log.Fatal(err)
	}
}

func run(packagePath string, names []string, outputFile string, verbose bool) error {
	cfg := &packages.Config{
		Mode: packages.NeedTypes | packages.NeedTypesInfo | packages.NeedSyntax |
			packages.NeedName | packages.NeedImports | packages.NeedDeps,
		// Some packages only compile as test builds (types shared with test
		// files); load both variants and prefer the plain one when it is
		// healthy.
		Tests: true,
	}
	pkgs, err := packages.Load(cfg, packagePath)
	if err != nil {
		return fmt.Errorf("failed to load package %s: %w", packagePath, err)
	}
	var plain, testVariant *packages.Package
	for _, p := range pkgs {
		if p.Name == "main" || strings.HasSuffix(p.PkgPath, ".test") ||
			strings.HasSuffix(p.Name, "_test") {
			continue
		}
		switch {
		case p.ID == p.PkgPath:
			plain = p
		case strings.Contains(p.ID, " ["):
			testVariant = p
		}
	}
	pkg := plain
	if pkg == nil || len(pkg.Errors) > 0 {
		if testVariant != nil && len(testVariant.Errors) == 0 {
			pkg = testVariant
		}
	}
	if pkg == nil {
		return fmt.Errorf("no suitable package found for %s", packagePath)
	}
	if len(pkg.Errors) > 0 {
		return fmt.Errorf("package %s has errors: %v", packagePath, pkg.Errors[0])
	}

	parser := codegen.NewParser()
	// Certification needs the full structural descriptor, never a shallow
	// delegation stub for types that already carry generated methods.
	parser.NoDelegation = true
	parser.AnnotationResolver = func(t types.Type) string {
		name := annotatedTypeName(t, pkg)
		if name == "" {
			return ""
		}
		return findAnnotateCall(pkg, name)
	}

	scope := pkg.Types.Scope()
	var out strings.Builder
	out.WriteString("import SszCert.Codec\n\n")
	out.WriteString("/-! Machine-checked SSZ certificates. Generated by dynssz-certify — do not edit. -/\n\n")
	out.WriteString("namespace Ssz\n\n")
	out.WriteString("/-- Stand-in bound for SSZ types without a declared limit (progressive\n")
	out.WriteString("    lists/bitlists). Unreachable: offsets cap wire-derived counts far below. -/\n")
	out.WriteString("def noLimit : Nat := 2 ^ 64\n\n")

	var registry []string
	for _, name := range names {
		obj := scope.Lookup(name)
		if obj == nil {
			return fmt.Errorf("type %s not found in package %s", name, pkg.PkgPath)
		}
		typeObj, ok := obj.(*types.TypeName)
		if !ok {
			return fmt.Errorf("%s is not a type", name)
		}

		var typeHints []ssztypes.SszTypeHint
		var sizeHints []ssztypes.SszSizeHint
		var maxSizeHints []ssztypes.SszMaxSizeHint
		if tag := findAnnotateCall(pkg, name); tag != "" {
			typeHints, sizeHints, maxSizeHints, err = ssztypes.ParseTags(tag)
			if err != nil {
				return fmt.Errorf("failed to parse annotation tag for %s: %w", name, err)
			}
		}

		desc, err := parser.GetTypeDescriptor(typeObj.Type(), typeHints, sizeHints, maxSizeHints)
		if err != nil {
			return fmt.Errorf("failed to build descriptor for %s: %w", name, err)
		}

		expr, err := leanExpr(desc)
		if err != nil {
			return fmt.Errorf("type %s: %w", name, err)
		}

		if verbose {
			log.Printf("certified %s", name)
		}

		fmt.Fprintf(&out, "/-- Certificate for `%s.%s`. -/\n", pkg.Name, name)
		fmt.Fprintf(&out, "def C_%s : Codec :=\n  %s\n\n", name, expr)
		fmt.Fprintf(&out, "/-- Decode-canonicity (P2) for `%s`: every accepted byte string is\n", name)
		fmt.Fprintf(&out, "    exactly the canonical serialization of its decoded value. -/\n")
		fmt.Fprintf(&out, "theorem C_%s_canonicity {bs : List UInt8} {v : Val}\n", name)
		fmt.Fprintf(&out, "    (h : C_%s.dec bs = some v) : C_%s.wt v ∧ C_%s.ser v = bs :=\n", name, name, name)
		fmt.Fprintf(&out, "  C_%s.canon h\n\n", name)
		fmt.Fprintf(&out, "/-- Roundtrip (P1) for `%s`. -/\n", name)
		fmt.Fprintf(&out, "theorem C_%s_roundtrip {v : Val} (hwt : C_%s.wt v) (hrep : C_%s.rep v) :\n", name, name, name)
		fmt.Fprintf(&out, "    C_%s.dec (C_%s.ser v) = some v :=\n", name, name)
		fmt.Fprintf(&out, "  C_%s.round hwt hrep\n\n", name)

		registry = append(registry, fmt.Sprintf("  (\"%s\", C_%s)", name, name))
	}

	out.WriteString("/-- Name-indexed certificate registry (for the oracle CLI). -/\n")
	out.WriteString("def certified : List (String × Codec) := [\n")
	out.WriteString(strings.Join(registry, ",\n"))
	out.WriteString("]\n\nend Ssz\n")

	if err := os.WriteFile(outputFile, []byte(out.String()), 0o644); err != nil {
		return fmt.Errorf("failed to write %s: %w", outputFile, err)
	}
	fmt.Printf("wrote %d certificates to %s\n", len(names), outputFile)
	return nil
}

// leanExpr translates an SSZ type descriptor into an expression over the
// verified codec combinators.
func leanExpr(desc *ssztypes.TypeDescriptor) (string, error) {
	switch desc.SszType {
	case ssztypes.SszBoolType:
		return "boolCodec", nil
	case ssztypes.SszUint8Type:
		return "(uintCodec 1)", nil
	case ssztypes.SszUint16Type:
		return "(uintCodec 2)", nil
	case ssztypes.SszUint32Type:
		return "(uintCodec 4)", nil
	case ssztypes.SszUint64Type:
		return "(uintCodec 8)", nil
	case ssztypes.SszUint128Type:
		return "(uintCodec 16)", nil
	case ssztypes.SszUint256Type:
		return "(uintCodec 32)", nil

	case ssztypes.SszContainerType, ssztypes.SszProgressiveContainerType:
		// Progressive containers serialize exactly like plain containers of
		// their declared fields; ssz-index gaps only affect merkleization.
		if desc.ContainerDesc == nil {
			return "", fmt.Errorf("container without field descriptors")
		}
		fields := make([]string, 0, len(desc.ContainerDesc.Fields))
		for i := range desc.ContainerDesc.Fields {
			f, err := leanExpr(desc.ContainerDesc.Fields[i].Type)
			if err != nil {
				return "", fmt.Errorf("field %s: %w", desc.ContainerDesc.Fields[i].Name, err)
			}
			fields = append(fields, f)
		}
		return "(containerCodec [" + strings.Join(fields, ", ") + "])", nil

	case ssztypes.SszVectorType:
		elem := desc.ElemDesc
		if elem == nil {
			return "", fmt.Errorf("vector without element descriptor")
		}
		n := desc.Len
		if n <= 0 {
			return "", fmt.Errorf("vector with non-positive length %d", n)
		}
		if elem.SszType == ssztypes.SszUint8Type {
			return fmt.Sprintf("(byteVectorCodec %d)", n), nil
		}
		e, err := leanExpr(elem)
		if err != nil {
			return "", err
		}
		if isFixedSize(elem) {
			if elem.Size <= 0 {
				return "", fmt.Errorf("fixed-size vector element with size %d", elem.Size)
			}
			return fmt.Sprintf("(vectorFixedCodec %s %d %d (by rfl))", e, elem.Size, n), nil
		}
		return fmt.Sprintf("(vectorVarCodec %s %d)", e, n), nil

	case ssztypes.SszListType, ssztypes.SszProgressiveListType:
		// Progressive lists serialize exactly like plain lists; the
		// progressive spine only affects merkleization.
		elem := desc.ElemDesc
		if elem == nil {
			return "", fmt.Errorf("list without element descriptor")
		}
		limit := limitExpr(desc)
		if elem.SszType == ssztypes.SszUint8Type {
			return fmt.Sprintf("(byteListCodec %s)", limit), nil
		}
		e, err := leanExpr(elem)
		if err != nil {
			return "", err
		}
		if isFixedSize(elem) {
			if elem.Size <= 0 {
				return "", fmt.Errorf("fixed-size list element with size %d", elem.Size)
			}
			return fmt.Sprintf("(listFixedCodec %s %d %s (by rfl) (by decide))", e, elem.Size, limit), nil
		}
		return fmt.Sprintf("(listVarCodec %s %s)", e, limit), nil

	case ssztypes.SszBitvectorType:
		bits := desc.BitSize
		if bits <= 0 {
			bits = desc.Size * 8
		}
		if bits <= 0 {
			return "", fmt.Errorf("bitvector with unknown bit size")
		}
		return fmt.Sprintf("(bitvectorCodec %d)", bits), nil

	case ssztypes.SszBitlistType, ssztypes.SszProgressiveBitlistType:
		return fmt.Sprintf("(bitlistCodec %s)", limitExpr(desc)), nil

	case ssztypes.SszCompatibleUnionType:
		if len(desc.UnionVariants) == 0 {
			return "", fmt.Errorf("compatible union without variants")
		}
		selectors := make([]int, 0, len(desc.UnionVariants))
		for sel := range desc.UnionVariants {
			selectors = append(selectors, int(sel))
		}
		sort.Ints(selectors)
		variants := make([]string, 0, len(selectors))
		for _, sel := range selectors {
			e, err := leanExpr(desc.UnionVariants[uint8(sel)])
			if err != nil {
				return "", fmt.Errorf("union variant %d: %w", sel, err)
			}
			variants = append(variants, fmt.Sprintf("(%d, %s)", sel, e))
		}
		return "(unionCodec [" + strings.Join(variants, ", ") + "])", nil
	}

	return "", fmt.Errorf("unsupported SSZ type %v (certificates cover the spec-defined SSZ surface)", desc.SszType)
}

// isFixedSize reports whether a descriptor denotes a fixed-size SSZ type
// (the authoritative signal is the IsDynamic flag, not the Size field).
func isFixedSize(d *ssztypes.TypeDescriptor) bool {
	return d.SszTypeFlags&ssztypes.SszTypeFlagIsDynamic == 0
}

// limitExpr renders a list/bitlist limit; types without a declared limit
// (progressive collections) get the unreachable stand-in bound.
func limitExpr(desc *ssztypes.TypeDescriptor) string {
	if desc.SszTypeFlags&ssztypes.SszTypeFlagHasLimit != 0 {
		return strconv.FormatUint(desc.Limit, 10)
	}
	return "noLimit"
}

// annotatedTypeName returns the bare name of a named type defined in pkg, or
// "" for anything else. Pointers are unwrapped.
func annotatedTypeName(t types.Type, pkg *packages.Package) string {
	if ptr, ok := t.(*types.Pointer); ok {
		t = ptr.Elem()
	}
	named, ok := t.(*types.Named)
	if !ok {
		return ""
	}
	obj := named.Obj()
	if obj.Pkg() == nil || obj.Pkg().Path() != pkg.PkgPath {
		return ""
	}
	return obj.Name()
}

// findAnnotateCall scans the package AST for sszutils.Annotate[typeName](...)
// calls and returns the merged tag string (a type may be annotated from
// several places, e.g. a hand-written constraint plus a generated ssz-static
// declaration).
func findAnnotateCall(pkg *packages.Package, typeName string) string {
	var tags []string
	seen := map[string]struct{}{}

	for _, file := range pkg.Syntax {
		sszutilsAlias := ""
		for _, imp := range file.Imports {
			path := strings.Trim(imp.Path.Value, `"`)
			if path == "github.com/pk910/dynamic-ssz/sszutils" {
				if imp.Name != nil {
					sszutilsAlias = imp.Name.Name
				} else {
					sszutilsAlias = "sszutils"
				}
				break
			}
		}
		if sszutilsAlias == "" {
			continue
		}

		for _, decl := range file.Decls {
			tag := findAnnotateCallInDecl(decl, sszutilsAlias, typeName)
			if tag != "" {
				if _, ok := seen[tag]; !ok {
					seen[tag] = struct{}{}
					tags = append(tags, tag)
				}
			}
		}
	}

	return strings.Join(tags, " ")
}

func findAnnotateCallInDecl(decl ast.Decl, alias, typeName string) string {
	switch d := decl.(type) {
	case *ast.GenDecl:
		if d.Tok != token.VAR {
			return ""
		}
		for _, spec := range d.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}
			for _, val := range vs.Values {
				if tag := matchAnnotateCall(val, alias, typeName); tag != "" {
					return tag
				}
			}
		}
	case *ast.FuncDecl:
		if d.Name.Name != "init" || d.Body == nil {
			return ""
		}
		for _, stmt := range d.Body.List {
			exprStmt, ok := stmt.(*ast.ExprStmt)
			if !ok {
				continue
			}
			if tag := matchAnnotateCall(exprStmt.X, alias, typeName); tag != "" {
				return tag
			}
		}
	}
	return ""
}

func matchAnnotateCall(expr ast.Expr, alias, typeName string) string {
	call, ok := expr.(*ast.CallExpr)
	if !ok || len(call.Args) != 1 {
		return ""
	}
	indexExpr, ok := call.Fun.(*ast.IndexExpr)
	if !ok {
		return ""
	}
	sel, ok := indexExpr.X.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != "Annotate" {
		return ""
	}
	ident, ok := sel.X.(*ast.Ident)
	if !ok || ident.Name != alias {
		return ""
	}
	typeIdent, ok := indexExpr.Index.(*ast.Ident)
	if !ok || typeIdent.Name != typeName {
		return ""
	}
	lit, ok := call.Args[0].(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return ""
	}
	if strings.HasPrefix(lit.Value, "`") {
		return strings.TrimPrefix(strings.TrimSuffix(lit.Value, "`"), "`")
	}
	tag, unquoteErr := strconv.Unquote(lit.Value)
	if unquoteErr != nil {
		return ""
	}
	return tag
}
